import type { JeeSubjectId } from '../data/jeeMainSyllabus';

/**
 * Question, response, scoring and attempt models for JEE practice.
 *
 * Source labels are mandatory and never inferred:
 *  - 'pyq'      : an officially published NTA question, with its paper reference and official key.
 *  - 'curated'  : an original Learnmate question with a human-verified answer key.
 *  - 'ai'       : generated by AI for practice; never presented as an official PYQ.
 */
export type QuestionSource = 'pyq' | 'curated' | 'ai';
export type QuestionType = 'mcq' | 'numerical';
export type QuestionDifficulty = 'easy' | 'medium' | 'hard';
export type VerificationStatus = 'draft' | 'pending_review' | 'verified' | 'rejected';

/** NTA final-key outcome for a question (official keys occasionally accept several answers or drop a question). */
export type KeyStatus = 'normal' | 'dropped';

export interface McqOption {
  id: 'A' | 'B' | 'C' | 'D';
  text: string;
}

export interface PyqProvenance {
  exam: 'JEE Main';
  year: number;
  session: 1 | 2;
  date: string; // ISO date of the exam shift, e.g. 2026-04-02
  shift: 1 | 2;
  questionNumber: number;
  paperUrl: string; // official NTA question paper
  answerKeyUrl: string; // official NTA final answer key
}

export interface CuratedProvenance {
  author: string;
  createdAt: string;
  notes?: string;
}

export interface Verification {
  status: VerificationStatus;
  reviewedBy?: string;
  reviewedAt?: string;
  notes?: string;
}

interface BankQuestionBase {
  id: string;
  source: Exclude<QuestionSource, 'ai'>;
  subjectId: JeeSubjectId;
  chapterId: string;
  topicIds: string[];
  difficulty: QuestionDifficulty;
  /** Markdown with inline LaTeX ($...$); rendered with KaTeX in the UI. */
  stem: string;
  explanation: string;
  keyStatus?: KeyStatus;
  /** Groups curated questions that together form one complete paper (e.g. a full-length mock). */
  paperSetId?: string;
  pyq?: PyqProvenance;
  curated?: CuratedProvenance;
  verification: Verification;
}

export interface BankMcqQuestion extends BankQuestionBase {
  type: 'mcq';
  options: [McqOption, McqOption, McqOption, McqOption];
  /** Normally one option; official final keys can accept more than one. */
  correctOptionIds: Array<McqOption['id']>;
}

export interface BankNumericalQuestion extends BankQuestionBase {
  type: 'numerical';
  /** JEE Main Section B answers are integers; official keys can accept more than one value. */
  acceptedIntegers: number[];
}

export type BankQuestion = BankMcqQuestion | BankNumericalQuestion;

/** What the client receives before submission: never contains answers or explanations. */
export type PublicQuestion =
  | {
      id: string;
      type: 'mcq';
      source: QuestionSource;
      subjectId?: JeeSubjectId;
      chapterId?: string;
      topicIds: string[];
      topicLabel: string;
      difficulty: QuestionDifficulty;
      stem: string;
      options: McqOption[];
    }
  | {
      id: string;
      type: 'numerical';
      source: QuestionSource;
      subjectId?: JeeSubjectId;
      chapterId?: string;
      topicIds: string[];
      topicLabel: string;
      difficulty: QuestionDifficulty;
      stem: string;
    };

/** A student's response. `null` means unanswered (or marked for review without an answer). */
export type QuestionResponse =
  | { type: 'mcq'; optionId: McqOption['id'] | null }
  | { type: 'numerical'; value: string | null };

export interface MarkingScheme {
  id: string;
  correct: number;
  incorrect: number;
  unanswered: number;
}

export type ResponseOutcome = 'correct' | 'incorrect' | 'unanswered' | 'dropped';

export interface ScoredQuestion {
  questionId: string;
  outcome: ResponseOutcome;
  marks: number;
  topicIds: string[];
  topicLabel: string;
  subjectId?: JeeSubjectId;
  chapterId?: string;
  response: QuestionResponse;
}

export interface ScoreBreakdown {
  rawMarks: number;
  maxMarks: number;
  correct: number;
  incorrect: number;
  unanswered: number;
  dropped: number;
  attempted: number;
  /** correct / attempted (0 when nothing attempted). */
  accuracy: number;
}

export interface AttemptScore extends ScoreBreakdown {
  scheme: MarkingScheme;
  questions: ScoredQuestion[];
  bySubject: Record<string, ScoreBreakdown>;
  byChapter: Record<string, ScoreBreakdown>;
  byTopic: Record<string, ScoreBreakdown>;
}

export type AttemptKind = 'ai_practice' | 'topic_practice' | 'sectional_test' | 'full_mock';

/**
 * Attempt v2: scored on the server from server-held answer keys. Stored alongside the legacy
 * QuizAttempt fields so existing progress views keep working.
 */
export interface AttemptV2Fields {
  schemaVersion: 2;
  kind: AttemptKind;
  questionSetId: string;
  sessionId?: string;
  sources: QuestionSource[];
  scoredBy: 'server';
  markingSchemeId: string;
  rawMarks: number;
  maxMarks: number;
  correctCount: number;
  incorrectCount: number;
  unansweredCount: number;
  /** Per-question outcome with stable syllabus topic ids when known. */
  outcomes: Array<{
    questionId: string;
    outcome: ResponseOutcome;
    topicIds: string[];
    topicLabel: string;
    chapterId?: string;
  }>;
}

/**
 * Study session: the central context for resources, tutor chat and practice.
 * Existing documents are referenced (never copied or moved) by resource ids.
 */
export interface StudySession {
  id: string;
  name: string;
  subjectId?: JeeSubjectId;
  chapterId?: string;
  topicIds: string[];
  /** Ids of StudyDocument resources attached to the session. */
  resourceIds: string[];
  createdAt: string;
  lastActiveAt: string;
  /** Set when the session was created automatically for a pre-existing document. */
  migratedFromDocumentId?: string;
  schemaVersion: 1;
}
